  @Post(':orderId/notes')
  addNote(@Param('orderId') orderId: string, @Body() body: NoteBody): number {
    const kept = this.notes.get(orderId) ?? [];
    const text = body.pinned === true ? `[pinned] ${body.text}` : body.text;
    kept.push(text);
    this.notes.set(orderId, kept);
    return kept.length;
  }

